        assert!(blocks[1].t_start_s >= blocks[0].t_end_s);
        // The block histogram was reset at the seam: the second
        // block's extremes are its own.
        assert_eq!(blocks[1].floor_ps, 2_000);
        assert_eq!(blocks[1].max_ps, 2_000);
    }

    /// A `RunCfg` with the given budget, sample override, and
    /// block count; everything else neutral.
    fn sizing_cfg(
        target_seconds: f64,
        samples_override: Option<u64>,
        blocks: u64,
    ) -> RunCfg<'static> {
        RunCfg {
            target_seconds,
            samples_override,
            inner_override: None,
            pin_cpus: &[],
            report_ticks: false,
            seam_probes: true,
            band_labels: BandLabels::Both,
            decimals: 1,
            settle_time_s: DEFAULT_SETTLE_TIME_S,
            warm_cap_s: DEFAULT_WARM_CAP_S,
            blocks,
            block_sleep_s: (0.0, 0.0),
            block_warmup_s: 0.0,
            record: None,
        }
    }

    #[test]
    fn block_samples_shares_the_budget_over_the_sample_cost() {
        // 5 s over 100 blocks is 50 ms a block; at 281 ns a
        // sample that is 177,935 samples.
        let cfg = sizing_cfg(5.0, None, 100);
        assert_eq!(block_samples(&cfg, 281.0), 177_935);
        // A bench slower than the block's share still runs one
        // sample per block.
        assert_eq!(block_samples(&cfg, 1e9), 1);
    }

    #[test]
    fn block_samples_rounds_a_fixed_count_up_to_whole_blocks() {
        let cfg = sizing_cfg(5.0, Some(1_000), 3);
        assert_eq!(block_samples(&cfg, 281.0), 334);
        let cfg = sizing_cfg(5.0, Some(1), 100);
        assert_eq!(block_samples(&cfg, 281.0), 1);
    }

    /// One probe at `at` seconds with the given floor (ps); the
    /// upper quantile sits a flat 0.8% above it, so `spread`
    /// never drives these cases.
    fn probe(at: f64, floor_ps: u64) -> ProbeSummary {
        ProbeSummary {
            t_start_s: at,
            over_floor: 0,
        }
    }

    /// Block stats over blocks with the given means (ns).
    fn stats_of(means: &[f64], replicated: bool) -> BlockStats {
        let blocks: Vec<BlockSummary> = means.iter().map(|&m| block_of(m)).collect();
        BlockStats::from_blocks(&blocks, replicated)
    }

    #[test]
    fn few_blocks_fit_a_mean_and_withhold_the_rest() {
        let one = stats_of(&[24.0], true);
        assert_eq!(one.blocks, 1);
        assert!((one.mean_ns - 24.0).abs() < f64::EPSILON);
        assert_eq!(one.ci95_ns, None);
        assert_eq!(one.lsc_ns, None);
        // Seven replicated blocks are still under the gate; eight fit.
        let seven = stats_of(&[23.0, 25.0, 24.0, 24.0, 23.0, 25.0, 24.0], true);
        assert_eq!(seven.ci95_ns, None);
        let eight = stats_of(&[23.0, 25.0, 24.0, 24.0, 23.0, 25.0, 24.0, 24.0], true);
        assert!(eight.ci95_ns.is_some_and(|c| c > 0.0));
        assert!(eight.lsc_ns.is_some_and(|l| l > 0.0));
    }

    #[test]
    fn clock_pair_no_suspend_gap() {
        let clocks = ClockPair::now();
        let gap = clocks.suspended_s();
        assert!(gap.abs() < 0.5, "unexpected clock divergence: {gap}");
    }

    #[test]
    fn saturating_record_clamps_above_bound() {
        let mut hist = new_hist();
        hist.saturating_record(HIST_HIGH_PS * 2);
        assert_eq!(hist.len(), 1);
        assert!(hist.max() >= HIST_HIGH_PS);
    }

    #[test]
    fn round_elapsed_ps_keeps_sub_ns_precision() {
        // 156 ns over 33 calls = 4.727 ns/call — recorded as
        // 4,727 ps instead of the 5 ns that ns-rounding gave.
        assert_eq!(round_elapsed_ps(156_000, 33), 4_727);
        // Saturates instead of overflowing on absurd inputs.
        assert_eq!(round_elapsed_ps(u128::MAX - 1, 1), u64::MAX);
    }
}

